def get_grads_to_reduce(self, i, partition_id):

    def get_reducible_portion(key):
        grad = self.param_dict[key].grad
        total_elements = grad.numel()
        start = self.grad_start_offset[i][partition_id][key]
        num_elements = min(total_elements - start,
                           self.partition_size[i] - self.grad_partition_insertion_offset[i][partition_id][key])
        if not pg_correctness_test:
            if num_elements == total_elements:
                return grad
            else:
                return grad.contiguous().view(-1).narrow(0, int(start), int(num_elements))
        else:
            if num_elements == total_elements:
                return grad.clone()
            else:
                return grad.clone().contiguous().view(-1).narrow(0, int(start), int(num_elements))

    grads_to_reduce = []
    for key in self.is_grad_computed[i][partition_id]:
        grad = get_reducible_portion(key)
        grads_to_reduce.append(grad)
    return grads_to_reduce

def unscale_and_clip_grads(self, grad_groups_flat, total_norm):
    if self.clip_grad == 0.0 and self.loss_scale == 1.0:
        return

    # compute combined scale factor for this group
    combined_scale = self.loss_scale
    if self.clip_grad > 0.:
        clip_norm = total_norm
        # step() rejects invalid norms; keep direct callers from interpreting
        # the negative sentinel as a finite clipping magnitude.
        if is_invalid_grad_norm(clip_norm):
            clip_norm = torch.tensor(float("inf"), dtype=torch.float, device=self.device)
        # norm is in fact norm*scale
        clip = ((clip_norm / self.loss_scale) + 1e-6) / self.clip_grad
        clip = torch.clamp(clip, min=1.0)
        combined_scale = clip * self.loss_scale

    for grad in grad_groups_flat:
        if isinstance(grad, list):
            sub_partitions = grad
            for g in sub_partitions:
                g.data.mul_(1. / combined_scale)
        else:
            grad.data.mul_(1. / combined_scale)

